 public static Item Compare(WfpVisibleSnapshot a,WfpVisibleSnapshot b){long now=Stopwatch.GetTimestamp();bool window=a!=null&&b!=null&&a.capturedTicks>0&&b.capturedTicks>=a.capturedTicks&&b.capturedTicks<=now&&(b.capturedTicks-a.capturedTicks)/(double)Stopwatch.Frequency<30;bool good=window&&a.complete&&b.complete;bool comparable=good&&!a.conditionsOpaque&&!b.conditionsOpaque&&!a.contextOpaque&&!b.contextOpaque&&a.weightsComplete&&b.weightsComplete&&a.subLayersComplete&&b.subLayersComplete;bool changed=good&&a.fingerprint!=b.fingerprint;string change=!good?"前后观察未完成或时间窗口过期":changed?"可见规则摘要发生变化":!comparable?"条件值、上下文或权重未完整比较，不能确认前后一致":"可见规则摘要前后一致";string counts=b==null?"未取得可见规则摘要":!b.complete?"可见规则读取未完成（"+(b.reason??"unknown")+"，代码 "+b.errorCode+"）":"可见 "+b.count+" 条（活动 "+b.active+"，禁用 "+b.disabled+"）；活动阻断 "+b.block+"、放行 "+b.permit+"、调用驱动 "+b.callout+"；带条件 "+b.conditional+" 条 / "+b.conditionCount+" 个条件（"+b.conditionKinds+" 种值类型、"+b.matchKinds+" 种匹配方式）；有效权重 "+b.weightKnown+"/"+b.count+(b.weightKnown>0?"（"+b.weightMin+"–"+b.weightMax+"）":"")+"；子层优先级 "+b.subLayerKnown+"/"+b.count+(b.subLayerKnown>0?"（"+b.subLayerMin+"–"+b.subLayerMax+"）":"")+"；持久标记 "+b.persistent+"，启动期标记 "+b.bootTime+"，清除动作权标记 "+b.clearAction+"；"+change;counts+="；仅限当前权限可见规则，不能确认全系统 IPv6 已阻断。";var item=new Item("ipv6-wfp-observation","unknown","Windows WFP 出站 IPv6 数据包层（只读）",counts,"仅返回调用者可读取的过滤器；条件值、不可见规则、代理及其他层未证实，不能证明系统已阻断。","按需核对权限及本机策略；不以此项判断安全通过。");item.evidencePhase="wfp-visible-snapshot";item.evidenceScope="outbound-ippacket-v6;readable-filters;before-after";item.failureCode=!good?"wfp-observation-unavailable":changed?"wfp-visible-change":!comparable?"wfp-comparison-incomplete":"visibility-unproven";bool denied=(a!=null&&(a.errorCode==5||a.errorCode==0x80070005))||(b!=null&&(b.errorCode==5||b.errorCode==0x80070005));if(denied)item.failureCode="wfp-access-denied";item.rawResult=change+"; before="+(a==null?"none":a.reason+":"+a.errorCode)+"; after="+(b==null?"none":b.reason+":"+b.errorCode);return ite